export async function ensureMovesData() {
  if (!_moveDataCache) {
    _moveDataCache = await fetch("/moves.json").then(r => r.json()).catch(() => null);
  }
  return _moveDataCache;
}

export function getMoveName(move, language, moveData) {
  const data = moveData || _moveDataCache;
  if (data && move) {
    const m = data[move.key || move.name];
    if (m?.names?.[language]) return m.names[language];
    if (m?.names?.en) return m.names.en;
  }
  return move?.name?.replace(/-/g, " ") || "";
}

